 "content": "def transform(grid):
    """Stamp the seed-color pattern wherever its marked cells align with zeros."""
    h, w = len(grid), len(grid[0])
    seed_color = next((v for row in grid for v in row if v not in (0, 3, 2, 7)), None)
    # ARC backgrounds vary; find the unique non-background seed color.
    if seed_color is None:
        return [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == seed_color]
    minr = min(r for r, c in points); maxr = max(r for r, c in points)
    minc = min(c for r, c in points); maxc = max(c for r, c in points)
    shape = [(r - minr, c - minc) for r, c in points]
    out = [row[:] for row in grid]
    for r0 in range(h - (maxr - minr + 1) + 1):
        for c0 in range(w - (maxc - minc + 1) + 1):
            if all(grid[r0 + dr][c0 + dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r0 + dr][c0 + dc] = seed_color
    return out
